use axum::{Router,Json,Form,extract::{State,Path},http::StatusCode,response::Html,routing::{get,post,delete}};use std::sync::{Arc,Mutex};use fokus::{Board,Create};
type Shared=Arc<Mutex<Board>>;
async fn list(State(state):State<Shared>)->Json<Vec<fokus::Task>>{Json(state.lock().unwrap().tasks.clone())}
async fn create(State(state):State<Shared>,Form(input):Form<Create>)->(StatusCode,Json<serde_json::Value>){match state.lock().unwrap().create(input){Ok(t)=>(StatusCode::CREATED,Json(serde_json::to_value(t).unwrap())),Err(e)=>(StatusCode::BAD_REQUEST,Json(serde_json::json!({"error":e})))}}
async fn toggle(State(state):State<Shared>,Path(id):Path<u64>)->(StatusCode,Json<serde_json::Value>){let ok=state.lock().unwrap().toggle(id);(if ok{StatusCode::OK}else{StatusCode::NOT_FOUND},Json(serde_json::json!({"updated":ok})))}
async fn remove(State(state):State<Shared>,Path(id):Path<u64>)->(StatusCode,Json<serde_json::Value>){let ok=state.lock().unwrap().delete(id);(if ok{StatusCode::OK}else{StatusCode::NOT_FOUND},Json(serde_json::json!({"deleted":ok})))}
#[tokio::main]async fn main(){let state=Arc::new(Mutex::new(Board::default()));let app=Router::new().route("/",get(||async{Html(include_str!("../index.html"))})).route("/health",get(||async{Json(serde_json::json!({"ok":true}))})).route("/api/tasks",get(list).post(create)).route("/api/tasks/{id}/toggle",post(toggle)).route("/api/tasks/{id}",delete(remove)).with_state(state);let host=std::env::var("HOST").unwrap_or("127.0.0.1".into());let port=std::env::var("PORT").unwrap_or("8080".into());let listener=tokio::net::TcpListener::bind(format!("{host}:{port}")).await.unwrap();axum::serve(listener,app).await.unwrap();}
